import {RECIPES,RECOVERY_RECIPE_CONFIG,MATERIALS,RARITY,eligibleRecoveryMaterials,potionEffect,recipeKnown} from './engine.js';
import {icon} from './icons.js';
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderRecoveryRecipe(s,{quality=0,quantities={},quote=null,error='',busy=false}={}){const recipe=RECIPES['potion-healing'],known=recipeKnown(s,recipe.id),materials=eligibleRecoveryMaterials(s,quality),effect=potionEffect('healing',quality),plannedUnits=materials.reduce((n,m)=>n+(Number.isSafeInteger(quantities[m.key])?Math.max(0,quantities[m.key]):0),0),plannedQuantity=plannedUnits*RECOVERY_RECIPE_CONFIG.outputPerUnit,plannedGold=plannedUnits*RECOVERY_RECIPE_CONFIG.coinCosts[quality],issue=error||(plannedGold>s.gold?'金币不足：需要 '+plannedGold+'，现有 '+s.gold:'');return `<section class="recoveryRecipe"><div class="recoveryHeading">${icon('recipeBook')}<div><span class="eyebrow">FIXED RECIPE</span><h2>治疗药剂 · 固定配方</h2></div></div>${!known?`<div class="recoveryLocked">${icon('recipeScroll')}<h3>尚未掌握</h3><p>向行商购买配方卷轴，永久掌握后即可制作。</p><button data-view="merchant">前往行商</button></div>`:`<div class="recoveryQuality">${RARITY.slice(0,4).map((name,q)=>`<button class="r${q}text" data-recovery-quality="${q}" aria-pressed="${quality===q}" ${busy?'disabled':''}>${name}</button>`).join('')}</div><div class="recoveryResult potionQ${quality}">${icon('potionHeal','anvil',quality)}<div><strong class="r${quality}text">治疗药剂 ×${quote?.quantity??plannedQuantity}</strong><small>恢复 ${Math.round(effect.healFraction*100)}% 最大生命 · 同品质产出</small></div><b>${quote?.gold??plannedGold} ◈</b></div><div class="recoveryMaterials">${materials.map(m=>`<div class="recoveryMaterial r${quality}">${icon(MATERIALS[m.material].icon,'anvil',quality)}<div><strong>${esc(m.material)}</strong><small>库存 ${m.count}</small></div><div class="recoveryQuantity"><button data-recovery-delta="-1" data-recovery-key="${esc(m.key)}" ${busy?'disabled':''}>−</button><input type="number" min="0" max="${Math.min(RECOVERY_RECIPE_CONFIG.maxBatch,m.count)}" value="${quantities[m.key]||0}" data-recovery-quantity="${esc(m.key)}" aria-label="${esc(m.material)}投入数量" ${busy?'disabled':''}><button data-recovery-delta="1" data-recovery-key="${esc(m.key)}" ${busy?'disabled':''}>＋</button><button data-recovery-max="${esc(m.key)}" ${busy?'disabled':''}>最多</button></div></div>`).join('')||'<p class="subtleText">暂无此品质的恢复类材料。</p>'}</div>${issue?`<p class="recoveryError" role="alert">${esc(issue)}</p>`:''}<div class="recoveryActions"><button data-recovery-clear="1" ${busy?'disabled':''}>清空</button><button class="primary" data-recovery-commit="1" ${busy||!quote||!quote.quantity?'disabled':''}>制作 ${quote?.quantity??plannedQuantity} 瓶 · ${quote?.gold??plannedGold}◈</button></div><p class="recoveryNote">每份同品质恢复类材料制作${RECOVERY_RECIPE_CONFIG.outputPerUnit}瓶；每批1—${RECOVERY_RECIPE_CONFIG.maxBatch}瓶，金币按瓶计算。<br>固定配方不随机品质，也不触发神赐；不受自由融合5份投入限制。</p>`}<p class="recoveryNote">出发前备药。离线战斗只收集材料，不会自动制药。</p></section>`;}
